{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "Berkeley Ban on Pricing Algorithms to Set Rents",
      "requirement": "Landlords are prohibited from using pricing algorithms that analyze competitor data to set rents or manage occupancy levels for residential units. Selling, licensing, or providing such pricing algorithms to Berkeley landlords is also unlawful.",
      "requirement_es": "Se prohíbe a los propietarios utilizar algoritmos de fijación de precios que analicen datos de competidores para fijar alquileres o gestionar niveles de ocupación en unidades residenciales. También es ilegal vender, licenciar o proporcionar dichos algoritmos de fijación de precios a los propietarios de Berkeley.",
      "key_value": {
        "label": "Civil penalty per violation",
        "value": "up to $1,000"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Products used for the purpose of establishing rent or income limits in accordance with affordable housing guidelines of a local, state, or federal government or other political subdivision",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "product used for the purpose of establishing rent or income limits in accordance with affordable housing guidelines"
              }
            ]
          }
        },
        {
          "description": "Any report published by a trade association that receives renter data and publishes it in an aggregated and anonymous manner",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": null,
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties of up to $1,000 per violation (each month a violation exists or continues, and each unit for which the algorithm was used, constitutes a separate violation), plus damages, injunctive relief, restitution/return of illegal profits, and reasonable attorney's fees and costs.",
      "source_citation": "Berkeley Mun. Code § 13.63.030",
      "quote": {
        "chunk": "c7",
        "start_words": "It shall be unlawful for a landlord",
        "end_words": "a separate and distinct violation."
      },
      "confidence": 0.95
    }
  ]
}
